"use strict";(globalThis.webpackChunkcake_recipes=globalThis.webpackChunkcake_recipes||[]).push([[4852],{78242(e,t,a){a.r(t),a.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>u,frontMatter:()=>l,metadata:()=>s,toc:()=>p});const s=JSON.parse('{"id":"module-04/mastery-quiz","title":"Module 4 Mastery Quiz: Fasteners, Bearings, and Shafts","description":"---","source":"@site/mechanical/module-04/4.5-mastery-quiz.mdx","sourceDirName":"module-04","slug":"/module-04/mastery-quiz","permalink":"/mechanical/module-04/mastery-quiz","draft":false,"unlisted":false,"editUrl":"https://github.com/telemarkfirst/telemarkfirst.github.io/tree/main/mechanical/module-04/4.5-mastery-quiz.mdx","tags":[],"version":"current","sidebarPosition":5,"frontMatter":{"id":"mastery-quiz","title":"Module 4 Mastery Quiz: Fasteners, Bearings, and Shafts","sidebar_label":"Module 4 \xb7 Mastery Quiz","sidebar_position":5},"sidebar":"mechanicalSidebar","previous":{"title":"4.4 \xb7 Stack-Ups","permalink":"/mechanical/module-04/spacers-and-stackups"},"next":{"title":"Overview","permalink":"/mechanical/module-05"}}');var o=a(74848),n=a(28453),r=a(15432),i=a(8274),h=a(54703);const l={id:"mastery-quiz",title:"Module 4 Mastery Quiz: Fasteners, Bearings, and Shafts",sidebar_label:"Module 4 \xb7 Mastery Quiz",sidebar_position:5},d="Module 4 Mastery Quiz: Fasteners, Bearings, and Shafts",c={},p=[{value:"I. Conceptual Questions",id:"i-conceptual-questions",level:2},{value:"II. Review the Assembly",id:"ii-review-the-assembly",level:2},{value:"III. Scored Check",id:"iii-scored-check",level:2}];function m(e){const t={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",pre:"pre",strong:"strong",...(0,n.R)(),...e.components},{Details:a}=t;return a||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"module-4-mastery-quiz-fasteners-bearings-and-shafts",children:"Module 4 Mastery Quiz: Fasteners, Bearings, and Shafts"})}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsx)(t.h2,{id:"i-conceptual-questions",children:"I. Conceptual Questions"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"1. How a Joint Carries Load:"})," Explain why a bolted joint that is snug but not properly tightened develops slop, even when the screw is far stronger than the load requires."]}),"\n",(0,o.jsxs)(a,{children:[(0,o.jsx)("summary",{children:"Show answer"}),(0,o.jsx)(t.p,{children:"A properly tightened screw stretches slightly, and that stretch clamps the two parts together. The friction between the clamped faces carries the load, and the parts do not move relative to each other."}),(0,o.jsx)(t.p,{children:"A snug screw generates little clamping force, so friction is negligible and the load transfers to the screw in shear. Because the clearance hole is larger than the screw, the parts shift until the hole wall contacts the screw shank. That shift is the slop, and it occurs regardless of screw strength: the screw is not failing, the joint is simply not clamped."})]}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"2. Symptom Versus Cause:"})," A team applies blue threadlocker to a screw that keeps backing out. It loosens again two matches later. What is the likely underlying cause and how should it be diagnosed?"]}),"\n",(0,o.jsxs)(a,{children:[(0,o.jsx)("summary",{children:"Show answer"}),(0,o.jsx)(t.p,{children:"Repeated loosening in one specific location usually means the joint itself is moving: the parts flex or shift relative to each other under load, and each cycle of movement lets the screw rotate back slightly. Threadlocker resists rotation but does not prevent the relative motion causing it, so it delays the failure rather than fixing it."}),(0,o.jsx)(t.p,{children:"Diagnosis: load the mechanism by hand and watch the joint for relative movement between the parts, and check whether the joint has only one fastener, which allows rotation about it. The fixes are structural: add a second fastener spaced away from the first, add a locating feature such as a dowel or a shoulder, or stiffen the flexing member."})]}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"3. Set Screws:"})," Why is a set screw bearing directly on a round shaft unreliable, and what are the ordered remedies?"]}),"\n",(0,o.jsxs)(a,{children:[(0,o.jsx)("summary",{children:"Show answer"}),(0,o.jsx)(t.p,{children:"A set screw on a round shaft contacts a curved surface at essentially a point, so it holds by digging into the shaft rather than by clamping. Torque reversals rock the hub slightly against that point contact, and the set screw backs out."}),(0,o.jsx)(t.p,{children:"Start by aligning the set screw with a machined flat so it bears on a positive surface. A second set screw at 90 degrees can resist the rotation that loosens the first, and blue threadlocker can retain the threads. A clamping hub provides a stronger alternative because it grips the shaft around its circumference."})]}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"4. Bearing Spacing:"})," A shaft carries a sprocket cantilevered 3 in beyond its two bearings, which are 1 in apart. Explain why this is a poor arrangement and what to change."]}),"\n",(0,o.jsxs)(a,{children:[(0,o.jsx)("summary",{children:"Show answer"}),(0,o.jsx)(t.p,{children:"A cantilevered load acts through a lever arm against the bearing pair. With bearings only 1 in apart and the load 3 in outboard, the reaction forces at each bearing are several times the applied load, and they act in opposite directions. That accelerates bearing wear, deflects the shaft, and lets the sprocket tip out of plane, which throws chain."}),(0,o.jsx)(t.p,{children:"Increase the bearing spacing first because tripling it cuts the reactions by roughly a factor of three. Next, shorten the cantilever by moving the sprocket inboard. If the cantilever is unavoidable, add a third support outboard of the load so the sprocket sits between supports."})]}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"5. Stack-Up Tolerance:"})," A stack contains six parts, each held to plus or minus 0.1 mm. What is the worst case position error, and give two design changes that reduce it."]}),"\n",(0,o.jsxs)(a,{children:[(0,o.jsx)("summary",{children:"Show answer"}),(0,o.jsx)(t.p,{children:"In the worst case the errors all accumulate in the same direction, giving plus or minus 0.6 mm."}),(0,o.jsx)(t.p,{children:"First, replace four 6 mm spacers with one 24 mm spacer to remove three tolerances from the chain. Then add a deliberate adjustment, such as a clamping collar, slotted mount, or shim pack, so you can absorb accumulated error during assembly."})]}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsx)(t.h2,{id:"ii-review-the-assembly",children:"II. Review the Assembly"}),"\n",(0,o.jsxs)(t.p,{children:["A team describes a drivetrain shaft assembly. ",(0,o.jsx)(t.strong,{children:"Identify the 2 errors and state the fix."})]}),"\n",(0,o.jsx)(t.pre,{children:(0,o.jsx)(t.code,{className:"language-text",children:"The dead axle passes through a single flanged bearing pressed\ninto the 3D printed side plate. The wheel is mounted on the\noutboard end of the axle, 2 in outside the bearing.\n\nThe wheel is retained by a set screw hub on the round axle,\nwith no flat. A stack of five washers sets the wheel spacing\nfrom the plate.\n\nAfter two practice sessions the wheel has developed visible\nwobble and the hub has rotated on the axle.\n"})}),"\n",(0,o.jsxs)(a,{children:[(0,o.jsx)("summary",{children:"Show answers"}),(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Error 1 - A single bearing supporting a cantilevered wheel, pressed into printed plastic."}),"\nOne bearing cannot resist tipping, so the wheel 2 in outboard pivots about it, which is the observed wobble. The problem is compounded by pressing the bearing into a 3D printed plate: printed plastic creeps under sustained load, so the interference holding the bearing relaxes and the bore deforms out of round."]}),(0,o.jsx)(t.pre,{children:(0,o.jsx)(t.code,{className:"language-text",children:"Fix: support the axle in two bearings, spaced as far apart as\nthe design allows, and keep the wheel between or close to the\nsupports. Press the bearings into aluminum, or retain them in\nthe printed part with a metal plate or clamping feature rather\nthan by interference alone.\n"})}),(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Error 2 - A set screw on a round axle with no flat, plus washers used as spacers."}),"\nA set screw contacting a curved surface holds by point contact and backs out under load reversal, which is why the hub rotated. Separately, five washers is an uncontrolled stack: washer thickness varies and is not a specified dimension, so the wheel spacing is unpredictable and contributes to the misalignment."]}),(0,o.jsx)(t.pre,{children:(0,o.jsx)(t.code,{className:"language-text",children:"Fix: use an axle with a machined flat and align the set screw\nto it, or use a clamping hub. Add blue threadlocker to the set\nscrew. Replace the five washers with a single spacer of the\nspecified length, and write the stack-up into the notebook.\n"})})]}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsx)(t.h2,{id:"iii-scored-check",children:"III. Scored Check"}),"\n",(0,o.jsx)(t.p,{children:"The questions above are for working something through. These are graded, so you can find out whether it stuck. Everything is scored in your browser."}),"\n",(0,o.jsx)(i.A,{lessonId:"module-04/mastery-quiz",questions:h.G["module-04"]}),"\n",(0,o.jsx)(r.A,{lessonId:"module-04/mastery-quiz",nextUnit:"/mechanical/module-05",nextUnitName:"Module 5: CAD With Onshape"})]})}function u(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(m,{...e})}):m(e)}},8274(e,t,a){a.d(t,{A:()=>M});var s=a(96540),o=a(61938),n=a(28883),r=a(99991);const i="quiz_cF9Z",h="header_xeWe",l="eyebrow_mc_C",d="title_USD7",c="subtitle_Vm7O",p="body_oW0N",m="question_lZ6r",u="prompt_O7Ua",g="options_Q5yu",w="option_NoJL",f="selected_SAix",b="correct_HcmQ",y="incorrect_Y7uO",x="marker_M_dd",v="explain_wbs2",k="actions_zG_d",T="button_so6H",A="secondary_Jhzk",j="score_NQOG",I="pass_jo16",W="fail_lTo4",q="progressTrack_R2ZB",z="progressFill_ZmTg",N="saved_ejhv";var S=a(74848);function M({lessonId:e,title:t="Scored Check",passMark:a=80,questions:M}){const{user:_}=(0,o.A)(),{markComplete:C,isComplete:B}=(0,n.p)(_),[R,D]=(0,s.useState)(()=>M.map(()=>null)),[F,O]=(0,s.useState)(!1),[U,H]=(0,s.useState)(!1),[P,Q]=(0,s.useState)(!1),$=R.filter(e=>null!==e).length,E=$===M.length,Y=(0,s.useMemo)(()=>R.filter((e,t)=>e===M[t].answer).length,[R,M]),G=M.length?Math.round(Y/M.length*100):0,Z=G>=a;return(0,S.jsxs)("section",{className:i,children:[(0,S.jsxs)("div",{className:h,children:[(0,S.jsxs)("p",{className:l,children:["// ",e,".check"]}),(0,S.jsx)("h3",{className:d,children:t}),(0,S.jsxs)("p",{className:c,children:[M.length," questions. ",a,"% to pass. Answers are graded in your browser and nothing is submitted anywhere."]}),(0,S.jsx)("div",{className:q,"aria-hidden":"true",children:(0,S.jsx)("div",{className:z,style:{width:$/M.length*100+"%"}})})]}),(0,S.jsxs)("div",{className:p,children:[M.map((e,t)=>(0,S.jsxs)("div",{className:m,children:[(0,S.jsxs)("p",{className:u,children:[t+1,". ",e.prompt]}),(0,S.jsx)("div",{className:g,role:"group","aria-label":e.prompt,children:e.options.map((a,s)=>{const o=R[t]===s,n=e.answer===s;let r=w;return F&&n?r=`${w} ${b}`:F&&o&&!n?r=`${w} ${y}`:o&&(r=`${w} ${f}`),(0,S.jsxs)("button",{type:"button",className:r,disabled:F,"aria-pressed":o,onClick:()=>{return e=t,a=s,void(F||D(t=>t.map((t,s)=>s===e?a:t)));var e,a},children:[(0,S.jsx)("span",{className:x,"aria-hidden":"true",children:F&&n?"\u2713":F&&o?"\u2715":String.fromCharCode(65+s)}),(0,S.jsx)("span",{children:a})]},a)})}),F&&(0,S.jsx)("p",{className:v,children:e.explain})]},e.prompt)),(0,S.jsx)("div",{className:k,children:F?(0,S.jsxs)(S.Fragment,{children:[(0,S.jsxs)("span",{className:`${j} ${Z?I:W}`,children:[Y," / ",M.length," correct (",G,"%)",Z?" // passed":" // review and retry"]}),(0,S.jsx)("button",{type:"button",className:`${T} ${A}`,onClick:function(){D(M.map(()=>null)),O(!1),Q(!1)},children:"Try again"}),Z&&!B(e)&&!P&&(0,S.jsx)("button",{type:"button",className:T,onClick:async function(){H(!0);try{await C(e),Q(!0)}catch(t){console.error("Telemark quiz save failed:",t),Q(!0)}finally{H(!1)}},disabled:U,children:U?"Saving...":"Record as complete"}),(P||Z&&B(e))&&(0,S.jsx)("span",{className:N,children:_?"synced to your account":"saved on this device"})]}):(0,S.jsx)("button",{type:"button",className:T,disabled:!E,onClick:function(){O(!0),(0,r.s)("quiz_graded",{lesson_id:e,score_percent:G,passed:G>=a})},children:E?"Grade my answers":M.length-$+" left"})})]})]})}},54703(e,t,a){a.d(t,{G:()=>s});const s={"module-00":[{prompt:"A scoring action is worth 6 points and takes 9 seconds. Another is worth 2 points and takes 4 seconds. Which is the better target on points per second alone?",options:["The 6 point action, at 0.67 per second","The 2 point action, at 0.5 per second","They are equal","Points per second cannot be compared across actions"],answer:0,explain:"6/9 = 0.67 against 2/4 = 0.5. That ranks them, but it does not settle the strategy: if the 9 second estimate ignores alignment time, the ranking can flip."},{prompt:"Which of these is a constraint rather than a requirement?",options:["The robot must score in the high goal","The robot must fit the starting size limit","The robot should cycle in under 10 seconds","The team will use mecanum wheels"],answer:1,explain:"The size limit comes from the manual and cannot be negotiated. Scoring high and cycle time are requirements you chose and could drop. Mecanum is a preference stated as though it were a constraint."},{prompt:"Why should the generating and judging phases of a brainstorm be separated?",options:["To make the meeting shorter","Because judging during generation makes people stop proposing ideas","Because bad ideas should never be written down","So the team lead can decide alone"],answer:1,explain:"Immediate criticism narrows the discussion before the team has generated enough alternatives. Separate the phases so each idea can be developed before the group compares it against the requirements."},{prompt:"A prototype takes two weeks to build. What is the main problem with that?",options:["It costs too much material","It answers the question too late to act on, and becomes too expensive to throw away","Prototypes should always be made from metal","Nothing, thorough prototypes are better"],answer:1,explain:"A prototype needs to answer its question early enough for the team to change direction. A two-week build delays that result and makes the team less willing to discard a weak concept."},{prompt:"Your team rejected three intake concepts. Why write down the reasons?",options:["Only to satisfy judges","Because the chosen concept may fail later and half the analysis is already done","To prove the team works hard","There is no reason to record rejected ideas"],answer:1,explain:"The notes explain the original decision and give the team a starting point if the chosen concept later fails. Recheck the alternatives using what the tests have since shown."}],"module-01":[{prompt:"Which notebook entry is most useful to a judge and to your team?",options:['"Worked on the intake today, made good progress"','"Intake acquired 7 of 12 elements at 2 in offset. Each failure rode up the funnel wall. Next: increase funnel angle to 35 degrees."','"The intake is done and works great"',"A photograph of the intake with no caption"],answer:1,explain:"It states the measurement, the trial count, the observed failure mode, and the next step. The others are opinions or undated activity logs."},{prompt:"How many trials are needed before calling a mechanism competition ready?",options:["1","3","10","25 or more"],answer:3,explain:"Three trials shows basic feasibility and ten gives rough reliability. A figure you can plan a match strategy around needs 25 or more."},{prompt:"In a weighted decision matrix, when must the criteria be weighted?",options:["After scoring, so the weights reflect the results","Before the options are scored","It does not matter","Only if the team disagrees"],answer:1,explain:"Weighting after scoring lets the team adjust the criteria around a preferred result. Set the weights first so they represent the strategy instead of the current favorite."},{prompt:"Concept A scores 61 and concept B scores 59 in your matrix. What should you do?",options:["Build A, it won","Rerun the matrix with different weights until one clearly wins","Prototype both, because the gap is smaller than the scoring noise","Pick whichever is cheaper"],answer:2,explain:"A 2 point margin is smaller than the uncertainty in subjective 1 to 5 scores. Treat the concepts as tied and compare rough prototypes with measured results."},{prompt:"A trial fails because someone bumped the robot. What should the notebook say?",options:["Nothing, discard it","Record it as a bumped trial with the reason","Count it as a normal failure","Restart the whole test from zero"],answer:1,explain:"Record the trial, identify the bump, and state whether it was excluded from the reliability calculation. Another reader can then reproduce how the result was calculated."}],"module-02":[{prompt:"Why must gloves be removed before using a drill press?",options:["They reduce grip on the workpiece","A caught glove pulls the whole hand into the tool, where bare skin would tear free","They are uncomfortable","They are only needed for chemicals"],answer:1,explain:"Gloves are right for handling sharp stock and wrong near any rotating spindle, because the glove is continuous material that wraps."},{prompt:"The tap drill for M4 x 0.7 is closest to which size?",options:["4.5 mm","4.0 mm","3.3 mm","2.5 mm"],answer:2,explain:"Tap drill is roughly major diameter minus pitch: 4 - 0.7 = 3.3 mm. 4.5 mm is the free clearance size, and 2.5 mm is the M3 tap drill."},{prompt:"Chips coming off an aluminum cut are turning blue. What does that mean?",options:["The cut is going well","The tool is too sharp","Too much heat, so slow the feed and add lubricant","The material is not really aluminum"],answer:2,explain:"Blue chips mean excessive heat. Hot aluminum welds to the cutting edge, which dulls it and generates more heat, so pushing harder makes it worse."},{prompt:"Why should you not lay out hole positions measured from a freshly bandsawn edge?",options:["It is faster to measure from the middle","A cut edge is not straight or square enough to be a reference surface","Bandsaw edges are too smooth to mark","You should always measure from the longest edge"],answer:1,explain:"Reference from an original extruded or machined surface, and record which edge you used so the next person uses the same one."},{prompt:"An M3 screw is tapped into 1/8 in aluminum plate. What is the concern?",options:["The screw is too long","3.175 mm of engagement is below the 1.5x diameter guideline of 4.5 mm","M3 cannot be tapped into aluminum","The plate will be too heavy"],answer:1,explain:"The threads will strip below the screw\u2019s own capacity. Use a nut, a threaded insert, tap into a thicker web, or accept the reduced strength deliberately."}],"module-03":[{prompt:"A frame rail bends 0.2 in under a hit and springs back undamaged. Why is this still a problem?",options:["It is not a problem, nothing broke","Mechanisms depend on geometry, so the intake moves 0.2 in and stops working during the hit","The rail will eventually fatigue","It makes the robot heavier"],answer:1,explain:"The rail was strong enough but not stiff enough. Because nothing breaks, the symptom looks intermittent and can be misdiagnosed as software or driver error."},{prompt:"A 16 in rail deflects too much. Which change helps most for the least weight?",options:["Switch from aluminum to steel","Add a support at the midpoint","Make the wall 50% thicker","Use a wider section"],answer:1,explain:"Deflection scales with the cube of span, so halving it cuts deflection to one eighth. Steel only gains a factor of about three and roughly triples the weight."},{prompt:"A 0.5 by 1.5 in bar is loaded flat instead of on edge. How much more does it deflect?",options:["3 times","9 times","2 times","The same, orientation does not matter"],answer:1,explain:"I = b*h^3/12, so height is cubed. (1.5/0.5)^2 = 9. Orientation is free stiffness, which is why it is checked before material changes."},{prompt:"Where should a polycarbonate plate NOT be used?",options:["As a guard over electronics","As an intake side wall","As a plate locating two shafts that must stay parallel","As a ball deflector"],answer:2,explain:"Polycarbonate has roughly a thirtieth of aluminum\u2019s stiffness and creeps under sustained load, so the shafts will not stay parallel."},{prompt:"When cutting weight, where should you look first?",options:["The lightest subsystem, since it is easiest","The heaviest subsystem, and weight high or far out on the robot","The fasteners","The battery"],answer:1,explain:"A 10% cut on the heaviest item saves more than deleting a small part. A pound at the end of an extended arm costs torque, tipping margin, and structure."}],"module-04":[{prompt:"A bolted joint is snug but not properly tightened. What happens under load?",options:["Nothing, the screw is strong enough","The parts shift within the clearance hole because there is little clamping force","The screw stretches permanently","The threads strip immediately"],answer:1,explain:"A tightened screw stretches and clamps the faces together. Friction between those faces carries the load. Without clamping, the load goes into the screw in shear and the parts move, which you feel as slop."},{prompt:"One screw keeps backing out even after blue threadlocker. What is the likely cause?",options:["The threadlocker was the wrong color","The joint itself is moving under load, so the fix is structural","The screw is too long","Stainless screws always loosen"],answer:1,explain:"Repeated loosening in one place usually means relative motion between the parts. Add a second fastener spaced away, add a locating feature, or stiffen the member."},{prompt:"What most improves a set screw holding a hub on a round shaft?",options:["More torque on the set screw","A longer set screw","Aligning it with a machined flat on the shaft","A larger diameter shaft"],answer:2,explain:"A set screw on a curved surface holds by point contact and rocks loose. A flat gives it a face to bear on. Better still is a clamping hub that grips the full circumference."},{prompt:"A sprocket is cantilevered 3 in beyond two bearings that are 1 in apart. What is the first fix?",options:["Use a stronger shaft","Increase the bearing spacing","Add threadlocker","Use a larger sprocket"],answer:1,explain:"Reaction forces scale with cantilever length over bearing spacing. Widen the bearing spacing first, then shorten the cantilever if needed."},{prompt:"Why should washers not be used as spacers in a stack-up?",options:["They are too heavy","Their thickness is not a controlled dimension, so position error accumulates","They corrode","They cannot be bought in the right sizes"],answer:1,explain:"Washer thickness varies. Use spacers with a specified length, and keep washers for spreading load under a fastener head."}],"module-05":[{prompt:"What can CAD NOT tell you about an intake?",options:["Whether it fits the starting envelope","Whether it interferes with the frame at 40 degrees","Whether it actually grips the game element","Whether it reaches the scoring position"],answer:2,explain:"CAD checks geometry. Friction, compliance, and how an element tumbles are physical behavior and need a prototype."},{prompt:"Why fully define every sketch before leaving it?",options:["It makes the file smaller","Under-defined geometry moves unpredictably when a dimension changes later","It is required by the software","It speeds up rendering"],answer:1,explain:"The part looks correct either way. The cost is paid at the first edit, usually by whoever inherits the model."},{prompt:"Two holes must stay symmetric about a plate\u2019s center. What is the right way to model that?",options:["Two dimensions from the left edge","A symmetry constraint","One dimension and a copy","Place them by eye and lock them"],answer:1,explain:"Dimensions from one edge encode positions. A symmetry constraint encodes intent, so the holes stay symmetric when the plate width changes."},{prompt:"An arm pivot is modeled with a fastened mate instead of a revolute mate. What is lost?",options:["Nothing, it is simpler","The assembly can never be driven through its range, so interference is only ever checked at one position","The mass properties become wrong","The drawing cannot be generated"],answer:1,explain:"Collisions frequently occur mid travel. An arm can clear at 0 and 110 degrees and strike the frame at 40."},{prompt:"Why reference a published version of an external document rather than its latest state?",options:["It loads faster","Otherwise someone editing that document silently changes your assembly","Versions use less storage","The software requires it"],answer:1,explain:"Referencing the tip means your model can break with no corresponding entry in your own edit history, which makes the cause very hard to find."}],"module-06":[{prompt:"A mechanism uses half of its available stall torque. Roughly what speed does it run at?",options:["Free speed","About half of free speed","About a quarter of free speed","Zero"],answer:1,explain:"Torque and speed trade linearly between the two endpoints, so half the stall torque leaves about half the free speed. Cycle times based on free speed are about twice too optimistic."},{prompt:"Where does a DC motor deliver peak mechanical power?",options:["At free speed","At stall","At half free speed and half stall torque","Just below stall"],answer:2,explain:"Power is torque multiplied by speed. Since torque falls linearly as speed rises, their product peaks at the midpoint of the motor curve."},{prompt:"Three stages of 4:1, 3:1, and 5:1 give what overall reduction?",options:["12:1","60:1","20:1","35:1"],answer:1,explain:"Reductions in series multiply: 4 x 3 x 5 = 60. At 95% per stage the efficiency compounds to about 86%, not 95%."},{prompt:"Roller chain must be ordered in what link count?",options:["Any count","An even count, to close without an offset link","An odd count","A multiple of five"],answer:1,explain:"Timing belts come in fixed tooth counts instead, so with belts you pick a stock length and place the shafts at the center distance it needs."},{prompt:"An arm does not stop in the same place twice, though the encoder readings are consistent. What is the mechanical cause?",options:["The encoder is broken","Backlash between the motor and the arm","The battery is low","The motor is undersized"],answer:1,explain:"The encoder measures the motor, not the arm. Backlash from each stage sums at the output, so the arm can sit anywhere within that play."}],"module-07":[{prompt:"A student proposes wider drive wheels to increase pushing force. Is that right?",options:["Yes, more contact area means more grip","No, friction force is mu times normal force and area does not appear","Yes, but only on soft tread","Only if the robot is heavy"],answer:1,explain:"Wider wheels help wear, load spreading, and behavior on uneven surfaces. For pushing force, the levers are tread compound, weight on driven wheels, and reduction."},{prompt:"Which is the safe side to design toward?",options:["Motor limited, so the wheels never slip","Traction limited, so the wheels slip before the motors stall","Neither matters","Whichever gives more top speed"],answer:1,explain:"A stalled motor draws full stall current, makes no motion, and turns it all into heat. Slipping wheels protect the motors and give the driver a predictable limit."},{prompt:"A team adds 5 lb of ballast low in the chassis. What happens?",options:["Both pushing force and acceleration improve","Pushing force improves, acceleration is roughly unchanged","Acceleration improves, pushing force is unchanged","Neither changes"],answer:1,explain:"Traction scales with weight, so pushing force rises. Acceleration is force over mass, and both went up together, so the ratio is about the same."},{prompt:"Middle wheels lift slightly during hard acceleration. Name a consequence beyond lost traction.",options:["The battery drains faster","Their encoders report counts that do not correspond to travel","The motors reverse","The wheels wear faster"],answer:1,explain:"A powered wheel with no load spins freely, corrupting any position estimate that uses drive encoders, at exactly the moment accuracy matters most."},{prompt:"An autonomous routine works on one robot and drifts on its identical twin, with the same code. Most likely cause?",options:["A software bug","Different measured odometry wheel diameters and pod offsets","A different battery","Different motors"],answer:1,explain:"The code depends on measured mechanical values. A 1% wheel diameter error is roughly 1 in over an 8 ft traverse, and offset errors grow with every turn."}],"module-08":[{prompt:"An intake fails one attempt in five. Why is that worse than being half a second slower per cycle?",options:["It is not worse","A failure costs a full retry cycle, not half a second","It looks bad to judges","It drains the battery"],answer:1,explain:"A failed acquisition means repositioning and reapproaching, often several seconds, plus disruption to the driver\u2019s rhythm. Reliability is the design target."},{prompt:"A three stage cascading slide is chosen for speed. What happens to the lifting force?",options:["It triples","It is unchanged","It is divided by three","It depends only on the motor"],answer:2,explain:"Speed and force trade exactly. Sizing the motor for extension speed and forgetting the force division is why a slide cannot lift its load."},{prompt:"At what arm angle is gravity torque highest?",options:["Vertical, pointing up","Horizontal","45 degrees","It is constant"],answer:1,explain:"Torque follows cos(theta) from horizontal, so cosine is 1 at horizontal and 0 at vertical. An arm sized at its stowed position will stall on the way through."},{prompt:"Why is a counterbalance stronger than gravity a problem?",options:["It wastes material","The arm drives itself upward, and does so uncontrolled when the motor is unpowered","It makes the arm too slow","It is not a problem, more margin is better"],answer:1,explain:"The motor then has to fight the spring downward, which is the same continuous torque problem reversed, and it is unsafe when power is removed."},{prompt:"A slide moves freely by hand on the bench and stalls loaded at full extension. Why?",options:["The motor is undersized","Under load the extended stages deflect, the rails go out of parallel, and friction rises","The string is too thin","The spool is too large"],answer:1,explain:"Deflection scales with the cube of extended length, and the bench test barely deflects. Test at the extreme of travel with the real load."}],"module-09":[{prompt:"Voltage drop must be calculated over what length?",options:["The one way run","Twice the one way run, because current flows out and back","Half the run","The straight line distance"],answer:1,explain:"Using the one way length halves the answer and always errs optimistically, which is why the mistake goes unnoticed until the robot underperforms."},{prompt:"A motor works on the bench and cuts out during matches, and the wire looks undamaged. What is the likely cause?",options:["A software bug","The conductor has fatigued and broken inside intact insulation, near the connector","The motor is failing","The battery is too small"],answer:1,explain:"Cable movement transfers into the connector, flexing the conductor where it is crimped. Anchor within a few inches with a service loop."},{prompt:"Which of these is the authoritative source for legal wiring?",options:["Another team\u2019s robot that passed inspection","A popular forum post","The current season\u2019s game manual","Last season\u2019s manual"],answer:2,explain:"Requirements change between seasons, other teams\u2019 robots may have been missed at inspection, and an inspector works from the manual."},{prompt:"Why label every wire at both ends with the configuration name?",options:["It looks professional","Because the code asks for that name, and diagnosis between matches takes minutes without labels","Inspectors require colored labels","It prevents shorts"],answer:1,explain:"If a wire moves and the configuration is not updated, the robot misbehaves in a way that is invisible from the code."},{prompt:"After fixing one failed inspection item, what should you do?",options:["Recheck only that item","Run the whole checklist again from the top","Nothing, go queue","Ask another team to check"],answer:1,explain:"Fixing one item frequently disturbs another: rerouting a cable can leave it taut at full extension, and re-seating a connector can leave it partly engaged."}],"module-10":[{prompt:"Why is building a prototype well usually a mistake?",options:["It is a waste of good material","It consumes the time advantage and makes the team unwilling to discard it","Prototypes should never work","It confuses the judges"],answer:1,explain:"A prototype earns its value by answering the question early. Effort invested also triggers the sunk cost trap, turning an experiment into a commitment."},{prompt:"A mechanism goes from 8/10 to 9/10 after a change. Did the change help?",options:["Yes, clearly","You cannot tell because that difference is within normal random variation","No, it got worse","Yes, by exactly 10%"],answer:1,explain:"Detecting a real difference needs enough trials that the change exceeds the noise, which for FTC purposes means 25 or more before and after."},{prompt:"Why should someone other than the builder run a reliability test?",options:["The builder is biased about the design","The builder unconsciously operates it in the way that works, which a driver will not","It is faster","To train more team members"],answer:1,explain:"Approach speed, angle, and small corrections get applied automatically and invisibly, so the measured reliability reflects an operator the robot will not have."},{prompt:"A slide stops moving and the team replaces the motor. What is wrong with that response?",options:["Nothing, the motor was the problem",'"The motor stalled" is a symptom; the cause is whatever made the load that high',"They should have replaced the whole slide","Motors never fail"],answer:1,explain:"Keep asking why until you reach a design decision you control, such as a flexing plate causing the rails to bind."},{prompt:"Surgical tubing snaps after two months of use. How should this be classified?",options:["A design failure needing a redesign","A build failure needing a checklist","A wear failure needing a replacement schedule and spares","An unpredictable event"],answer:2,explain:"Misclassifying wastes effort: redesigning a wear item spends hours on something working as intended."}],"module-11":[{prompt:"Why is specifying every dimension to plus or minus 0.001 in a poor decision?",options:["It is impossible to achieve","Tolerance is a cost, and it hides which dimensions actually matter","It makes the part heavier","Drawings cannot show that precision"],answer:1,explain:"Holding a thousandth needs reaming or boring and measurement of every feature. Applied everywhere, the fabricator cannot tell which features are real requirements."},{prompt:"A drilled hole and an FDM printed hole of the same nominal size differ how?",options:["Both come out oversize","Both come out undersize","Drilled comes out oversize, printed comes out undersize","Drilled comes out undersize, printed comes out oversize"],answer:2,explain:"They err in opposite directions, so a precision drilled bore should be reamed and a printed hole should be modeled oversize or drilled after printing."},{prompt:"A printed bracket fails far below the load an equivalent aluminum part would carry. Most likely cause?",options:["The plastic is defective","The load is trying to separate the print layers","The infill percentage is too low","The part is too thin overall"],answer:1,explain:"FDM parts are anisotropic and the layer bond is much weaker than material within a layer. Orientation is a design decision that belongs on the drawing."},{prompt:"A team measured the robot in the shop and still failed sizing at inspection. Most likely reason?",options:["The inspector made a mistake","It was measured in a tidy configuration rather than the true starting configuration, or something was added since","The rules changed at the event","The sizing box was wrong"],answer:1,explain:"A guard, a thicker cable, or zip tie tails all count, and a robot measured exactly at the limit fails because measurement is not perfectly repeatable."},{prompt:"A mechanism breaks with two matches until yours. What is the first triage question?",options:["How do we fix it properly?","Can the robot play safely without it?","Who broke it?","Should we forfeit?"],answer:1,explain:"A half completed proper repair means missing the match with the robot disassembled. Play degraded, swap a spare, or make a safe temporary fix, then repair properly later."}],"module-12":[{prompt:"What is the minimum clearance for a screw passing through a hole?",options:["0.05 mm per side","0.15 mm per side","0.5 mm per side","No clearance is needed"],answer:1,explain:"0.15 mm per side, so 0.3 mm on the diameter. It has to absorb drill error, position error, fastener runout, and surface finish together."},{prompt:"The M3 close clearance hole is which size?",options:["2.5 mm","3.0 mm","3.2 mm","3.6 mm"],answer:2,explain:"3.2 mm close, 3.4 mm free. 2.5 mm is the tap drill, and 3.0 mm is the screw itself, which binds."},{prompt:"Minimum thread engagement for M3 in aluminium?",options:["1.5 mm","3.0 mm","4.5 mm","9.0 mm"],answer:2,explain:"1.5 times the diameter. 1/8 in plate is 3.175 mm, which is below standard, so use a nut, an insert, or a thicker section."},{prompt:"A shaft spins freely with one bearing and stiffly with both. What does that mean?",options:["The bearings are the wrong size","The two bores are not coaxial","The shaft is too long","That is normal"],answer:1,explain:"The shaft bends to pass through both, which permanently loads the bearings and adds friction. Ten seconds to check during assembly, a spacer to fix."},{prompt:"Why is a safety factor of 6 also a mistake?",options:["It is not, more margin is always better","Margin is bought with reduction, and reduction costs speed proportionally","It makes the part too heavy to move","It voids the warranty"],answer:1,explain:"An arm with six times the needed torque takes several seconds to raise and loses the cycle it was built for. Aim for 2 to 3 and spend the rest on speed."}],"module-13":[{prompt:"Why does a compliant intake tolerate position error that a rigid claw cannot?",options:["It grips harder","Grip force becomes a function of deformation rather than exact width","It moves faster","Compliant materials have higher friction"],answer:1,explain:"N is roughly kx once the element deforms the compliant part, so a few millimetres of error changes the grip a little instead of removing it entirely."},{prompt:"A three stage cascading lift extends three times as fast per rotation. What else is tripled?",options:["Nothing, it is free","The force in the cable","The stage stiffness","The motor efficiency"],answer:1,explain:"Work is conserved, so the trade is the same as gearing for speed. This is why cascading lifts fail at the cable and its termination rather than in the slides."},{prompt:"What does a parallelogram four-bar guarantee?",options:["Constant speed at the end effector","The far member stays parallel to the fixed member throughout the motion","Zero backlash","Maximum reach for a given bar length"],answer:1,explain:"It is an exact geometric result, not an approximation, which is why the end effector holds its angle with no sensor and no second motor."},{prompt:"How does a virtual four-bar fail?",options:["The bar bends visibly","The belt skips a tooth, permanently and silently","It cannot reach full extension","The pivots seize"],answer:1,explain:"The angle is then wrong by that tooth for the rest of the match and nothing reports it. Belt tension and wrap angle are what prevent it."},{prompt:"Why does a dead wheel measure position better than a drive wheel?",options:["It has a better encoder","It carries almost no load and transmits no torque, so it does not slip","It is larger","It is closer to the centre of the robot"],answer:1,explain:"It measures the floor rather than the motor. The general principle is that odometry works by decoupling measurement from actuation."}]};Object.keys(s).length}}]);